-- Swiss desktop: Neovim colours from tokens/{light,dark}.env. Generated by swiss-build; do not edit here.
-- Linked as ~/.config/nvim/colors/swiss.lua. Both modes are here; 'background' picks one (lua/plugins/swiss.lua sets it
-- from the desktop's mode file and follows it). Ink on paper: keywords in bold ink, comments faint italic, the
-- terminal palette for strings, numbers and types, and the one red only where something is "here" (the cursor, the
-- current line number, the current match) or wrong.

local palettes = {
  light = {
    bg = "#@light.background@", surface = "#@light.surface@", surface2 = "#@light.surface2@",
    text = "#@light.text@", text2 = "#@light.text2@", muted = "#@light.muted@",
    border = "#@light.border@", border_strong = "#@light.border_strong@",
