    ansi = { "#@light.ansi0@", "#@light.ansi1@", "#@light.ansi2@", "#@light.ansi3@", "#@light.ansi4@", "#@light.ansi5@",
             "#@light.ansi6@", "#@light.ansi7@", "#@light.ansi8@", "#@light.ansi9@", "#@light.ansi10@", "#@light.ansi11@",
             "#@light.ansi12@", "#@light.ansi13@", "#@light.ansi14@", "#@light.ansi15@" },
  },
  dark = {
    bg = "#@dark.background@", surface = "#@dark.surface@", surface2 = "#@dark.surface2@",
    text = "#@dark.text@", text2 = "#@dark.text2@", muted = "#@dark.muted@",
    border = "#@dark.border@", border_strong = "#@dark.border_strong@",
    accent = "#@dark.accent@", accent_fill = "#@dark.accent_fill@", accent_fg = "#@dark.accent_fg@",
    selection = "#@dark.selection@",
    success = "#@dark.success@", warning = "#@dark.warning@", error = "#@dark.error@", info = "#@dark.info@",
    ansi = { "#@dark.ansi0@", "#@dark.ansi1@", "#@dark.ansi2@", "#@dark.ansi3@", "#@dark.ansi4@", "#@dark.ansi5@",
             "#@dark.ansi6@", "#@dark.ansi7@", "#@dark.ansi8@", "#@dark.ansi9@", "#@dark.ansi10@", "#@dark.ansi11@",
             "#@dark.ansi12@", "#@dark.ansi13@", "#@dark.ansi14@", "#@dark.ansi15@" },
  },
}

vim.cmd("highlight clear")
if vim.fn.exists("syntax_on") == 1 then vim.cmd("syntax reset") end
vim.g.colors_name = "swiss"

local c = palettes[vim.o.background] or palettes.dark
local green, yellow, blue, magenta, cyan = c.ansi[3], c.ansi[4], c.ansi[5], c.ansi[6], c.ansi[7]

-- a over b by t (0..1), for tinted backgrounds (diff, diagnostics).
local function blend(a, b, t)
  local function rgb(h) return tonumber(h:sub(2, 3), 16), tonumber(h:sub(4, 5), 16), tonumber(h:sub(6, 7), 16) end
  local ar, ag, ab = rgb(a)
  local br, bg_, bb = rgb(b)
  local function mix(x, y) return math.floor(x * t + y * (1 - t) + 0.5) end
  return string.format("#%02X%02X%02X", mix(ar, br), mix(ag, bg_), mix(ab, bb))
end

